89	     * these (compared case-insensitively) is rejected. Values are stored lower-cased for comparison.
90	     */
91	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
92	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
93	
94	    /**
95	     * Dedicated audit logger. Successful side-effecting operations (such as creating an owner) emit a
96	     * line here so audit trails can be captured independently of application logging.
97	     */
98	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
