264	    @Override
265	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
266	        Owner owner = this.clinicService.findOwnerById(ownerId);
267	        if (owner != null) {
268	            Pet pet = owner.getPet(petId);
269	            if (pet != null) {
270	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
271	            }
272	        }
273	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
274	    }
275	
276	    /**
277	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
278	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
279	     *
280	     * @param fields the submitted owner fields
281	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
282	     *                                        {@code null} or blank, or if the owner supplies no address
283	     *                                        in either form (a blank structured {@code addressLine1} and a
284	     *                                        blank flat {@code address}, each measured after normalization)
285	     */
286	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
287	        List<String> missing = new ArrayList<>();
288	        if (isBlank(fields.getFirstName())) {
289	            missing.add("firstName");
290	        }
291	        if (isBlank(fields.getLastName())) {
292	            missing.add("lastName");
293	        }
294	        boolean hasStructuredAddress = !isBlank(normalizeAddress(fields.getAddressLine1()));
295	        boolean hasFlatAddress = !isBlank(normalizeAddress(fields.getAddress()));
296	        if (!hasStructuredAddress && !hasFlatAddress) {
297	            missing.add("address");
298	        }
299	        if (isBlank(fields.getCity())) {
300	            missing.add("city");
301	        }
302	        if (isBlank(fields.getTelephone())) {
303	            missing.add("telephone");
304	        }
305	        if (!missing.isEmpty()) {
306	            throw new RequiredFieldsMissingException(missing);
307	        }
308	    }
309	
310	    private boolean isBlank(String value) {
311	        return value == null || value.isBlank();
312	    }
313	
314	    /**
315	     * Inclusive 4-digit postcode ranges permitted per city region, keyed by the region derived from the
316	     * city via {@link OwnerLocality}: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A region absent from
317	     * this table (i.e. {@code "UNKNOWN"}) imposes no range constraint, so any 4-digit postcode is accepted.
318	     */
319	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
320	        "NSW", new int[] {2000, 2099},
321	        "VIC", new int[] {3000, 3099},
322	        "QLD", new int[] {4000, 4099});
323	
324	    /**
325	     * Validates an owner's {@code postcode} when present. Postcode is optional: a {@code null} value is
326	     * accepted and left absent, keeping the create contract backward-compatible. When supplied it must be
327	     * a 4-digit value, and it must fall within the inclusive range for the city's region (NSW 2000-2099,
328	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
329	     *
330	     * @param postcode the submitted postcode, or {@code null} when omitted
331	     * @param city the owner's city, used to derive the region whose range constrains the postcode
332	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for the
333	     *                                  city's region
334	     */
335	    private void validatePostcode(String postcode, String city) {
336	        if (postcode == null) {
337	            return;
338	        }
339	        if (!postcode.matches("[0-9]{4}")) {
340	            throw new InvalidPostcodeException(postcode);
341	        }
342	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.of(city));
343	        if (range == null) {
344	            return;
345	        }
346	        int value = Integer.parseInt(postcode);
347	        if (value < range[0] || value > range[1]) {
348	            throw new InvalidPostcodeException(postcode);
349	        }
350	    }
351	
352	    /**
353	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
354	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
355	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
356	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
357	     * <p>
358	     * Where a per-country rule is defined the national-number length is validated against the country
359	     * code: {@code '+61'} (Australia) requires exactly 9 national digits and {@code '+1'} (NANP)
360	     * requires exactly 10.
361	     *
362	     * @param telephone the raw telephone value from the request
363	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
364	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
365	     */
366	    private String normalizeTelephone(String telephone) {
367	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
368	        String digits;
369	        if (cleaned.startsWith("+")) {
370	            digits = cleaned.substring(1);
371	        } else {
372	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
373	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
374	            digits = "61" + national;
375	        }
376	        if (!digits.matches("[0-9]{8,15}")) {
377	            throw new InvalidTelephoneException(cleaned);
378	        }
379	        // Validate the national-number length against the country code where a rule is defined.
380	        if (digits.startsWith("61") && digits.length() - 2 != 9) {
381	            throw new InvalidTelephoneException(cleaned);
382	        }
383	        if (digits.startsWith("1") && digits.length() - 1 != 10) {
384	            throw new InvalidTelephoneException(cleaned);
385	        }
386	        return "+" + digits;
387	    }
388	
389	    /**
390	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
391	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
392	     * lower-cased.
393	     *
394	     * @param email the raw email value from the request, or {@code null} if omitted
395	     * @return the lower-cased email, or {@code null} if none was supplied
396	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
397	     */
398	    private String normalizeEmail(String email) {
399	        if (email == null) {
400	            return null;
401	        }
402	        String trimmed = email.strip();
403	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
404	            throw new InvalidEmailException(email);
405	        }
406	        String normalized = trimmed.toLowerCase(Locale.ROOT);
407	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
408	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
409	            throw new DisposableEmailDomainException(domain);
410	        }
411	        return normalized;
412	    }
413	
414	    /**
415	     * Applies the owner's address in whichever form the request supplied, preferring the structured
416	     * fields. When a non-blank {@code addressLine1} is present, {@code addressLine1} and (when present)
417	     * {@code addressLine2} are normalized in place and the flat {@code address} is set to the composed
418	     * value: the normalized {@code addressLine1}, with a single space and the normalized
419	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the structured
420	     * lines are cleared and the flat {@code address} is normalized on its own, keeping the earlier
421	     * flat-address contract backward-compatible.
422	     *
423	     * @param owner the owner being created, mapped straight from the request
424	     */
425	    private void applyAddress(Owner owner) {
426	        if (!isBlank(owner.getAddressLine1())) {
427	            String line1 = normalizeAddress(owner.getAddressLine1());
428	            owner.setAddressLine1(line1);
429	            String composed = line1;
430	            if (!isBlank(owner.getAddressLine2())) {
431	                String line2 = normalizeAddress(owner.getAddressLine2());
432	                owner.setAddressLine2(line2);
433	                composed = line1 + " " + line2;
434	            } else {
435	                owner.setAddressLine2(null);
436	            }
437	            owner.setAddress(composed);
438	        } else {
439	            owner.setAddressLine1(null);
440	            owner.setAddressLine2(null);
441	            owner.setAddress(normalizeAddress(owner.getAddress()));
442	        }
443	    }
444	
445	    /**
446	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
447	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
448	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
449	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
450	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
451	     *
452	     * @param address the raw address value from the request (may be {@code null})
453	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
454	     */
455	    private String normalizeAddress(String address) {
456	        if (address == null) {
457	            return "";
458	        }
459	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
460	        if (collapsed.isEmpty()) {
461	            return "";
462	        }
463	        String[] tokens = collapsed.split(" ");
464	        StringBuilder sb = new StringBuilder(collapsed.length());
465	        for (int i = 0; i < tokens.length; i++) {
466	            if (i > 0) {
467	                sb.append(' ');
468	            }
469	            sb.append(expandAddressAbbreviation(tokens[i]));
470	        }
471	        return sb.toString();
472	    }
473	
474	    /**
475	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
476	     * returns the token unchanged when it is not a recognised abbreviation.
477	     *
478	     * @param token an upper-cased whole-word address token
479	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
480	     */
481	    private String expandAddressAbbreviation(String token) {
482	        return switch (token) {
483	            case "ST" -> "STREET";
484	            case "RD" -> "ROAD";
485	            case "AVE" -> "AVENUE";
486	            default -> token;
487	        };
488	    }
489	
490	    /**
491	     * Builds the customer code assigned to a newly created owner, formatted {@code '<REGION>-<HASH8>'}
492	     * where {@code REGION} is the region derived from the owner's postcode (falling back to the city when
493	     * the postcode resolves to no known region), the same derivation that yields the owner's locality, and
494	     * {@code HASH8} is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
495	     * normalized telephone concatenated with the owner's last name (e.g. {@code 'NSW-1A2B3C4D'}).
496	     * <p>
497	     * Should the computed code collide with an existing owner's {@code customerCode}, it is de-duplicated
498	     * by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a value not already
499	     * held by any existing owner; the de-duplicated code is returned.
500	     *
501	     * @param owner the owner being created, with normalized telephone and postcode already set
502	     * @return the assigned, collision-free customer code
503	     */
504	    private String generateCustomerCode(Owner owner) {
505	        String region = OwnerLocality.of(owner.getCity(), owner.getPostcode());
506	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
507	            .substring(0, 8).toUpperCase(Locale.ROOT);
508	        String base = region + "-" + hash8;
509	        Set<String> existing = this.clinicService.findAllOwners().stream()
510	            .map(Owner::getCustomerCode)
511	            .filter(code -> code != null)
512	            .collect(java.util.stream.Collectors.toSet());
513	        if (!existing.contains(base)) {
514	            return base;
515	        }
516	        int n = 2;
517	        while (existing.contains(base + "-" + n)) {
518	            n++;
519	        }
520	        return base + "-" + n;
521	    }
522	
523	    /**
524	     * Computes the full lower-case hex SHA-256 digest of the UTF-8 bytes of the given value.
525	     *
526	     * @param value the value to hash
527	     * @return the 64-character lower-case hex SHA-256 digest
528	     */
529	    private String sha256Hex(String value) {
530	        try {
531	            byte[] digest = MessageDigest.getInstance("SHA-256")
532	                .digest(value.getBytes(StandardCharsets.UTF_8));
533	            StringBuilder sb = new StringBuilder(digest.length * 2);
534	            for (byte b : digest) {
535	                sb.append(String.format("%02x", b));
536	            }
537	            return sb.toString();
538	        } catch (NoSuchAlgorithmException e) {
539	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
540	        }
541	    }
542	
543	    /**
544	     * Counts how many existing owners already share the given first name and last name, compared
545	     * case-insensitively. The count is taken before the new owner is persisted, so it excludes the
546	     * owner being created.
547	     *
548	     * @param firstName the first name of the owner being created
549	     * @param lastName the last name of the owner being created
550	     * @return the number of existing owners with the same first and last name (case-insensitively)
551	     */
552	    private int countNamesakes(String firstName, String lastName) {
553	        return (int) this.clinicService.findAllOwners().stream()
554	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
555	                && lastName.equalsIgnoreCase(existing.getLastName()))
556	            .count();
557	    }
558	
559	    /**
560	     * Computes the size of the owner's household: the number of existing owners already sharing the given
561	     * {@code householdId} plus the owner being created itself. The existing count is taken before the new
562	     * owner is persisted, so adding one for the owner yields the household's total membership including it
563	     * (e.g. two existing members give a household size of 3 for the third member). Households are keyed on
564	     * the deterministic {@code householdId} (derived from last name and postcode).
565	     *
566	     * @param householdId the computed household identifier of the owner being created
567	     * @return the household size including the owner being created (at least 1)
568	     */
569	    private int countHouseholdSize(String householdId) {
570	        long existing = this.clinicService.findAllOwners().stream()
571	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
572	            .count();
573	        return (int) existing + 1;
574	    }
575	
576	    /**
577	     * The maximum number of owners permitted in a single city. A create request whose city already
578	     * holds this many owners is rejected.
579	     */
580	    private static final int CITY_OWNER_LIMIT = 50;
581	
582	    /**
583	     * Rejects a create request whose city already contains {@link #CITY_OWNER_LIMIT} or more owners.
584	     * Cities are matched case-insensitively, mirroring the per-city customer-code sequence, so owners
585	     * differing only in the casing of their city share one capacity pool. The count is taken before the
586	     * new owner is persisted, so it excludes the owner being created.
587	     *
588	     * @param city the city of the owner being created
589	     * @throws CityOwnerLimitExceededException if the city already holds the maximum number of owners
590	     */
591	    private void rejectCityAtCapacity(String city) {
592	        long existing = this.clinicService.findAllOwners().stream()
593	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
594	            .count();
595	        if (existing >= CITY_OWNER_LIMIT) {
596	            throw new CityOwnerLimitExceededException(city, CITY_OWNER_LIMIT);
597	        }
598	    }
599	
600	    /**
601	     * The maximum number of owners permitted to be created in a single day. A create request whose
602	     * registration date already holds this many owners is rejected.
603	     */
604	    private static final int DAILY_OWNER_LIMIT = 100;
605	
606	    /**
607	     * Rejects a create request when {@link #DAILY_OWNER_LIMIT} or more owners have already been created
608	     * on the same day, compared by {@code registrationDate}. The count is taken before the new owner is
609	     * persisted, so it excludes the owner being created.
610	     *
611	     * @param registrationDate the registration date of the owner being created
612	     * @throws DailyOwnerLimitExceededException if the day already holds the maximum number of owners
613	     */
614	    /**
615	     * The fixed list of public holidays that are not treated as business days. A registration date that
616	     * lands on one of these dates is rolled forward, just as a weekend is.
617	     */
618	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
619	        LocalDate.of(2026, 1, 1),
620	        LocalDate.of(2026, 1, 26),
621	        LocalDate.of(2026, 4, 25),
622	        LocalDate.of(2026, 12, 25),
623	        LocalDate.of(2026, 12, 28));
624	
625	    /**
626	     * Adjusts an effective registration date so that it always falls on a business day. When the given
627	     * date is a Saturday, a Sunday or a listed public holiday it is rolled forward one day at a time until
628	     * it reaches the next non-holiday business day; a weekday that is not a holiday is returned unchanged.
629	     * This applies equally to a date supplied in the request and to a date defaulted to the server date, and
630	     * the adjusted value is what becomes the owner's {@code registrationDate}, so every value derived from it
631	     * (the membership number's year segment, the daily create-limit count) uses the business-day-adjusted
632	     * date.
633	     *
634	     * @param date the effective registration date, supplied or defaulted
635	     * @return the same date when it is a business day, otherwise the next non-holiday business day
636	     */
637	    private LocalDate rollToBusinessDay(LocalDate date) {
638	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
639	            date = date.plusDays(1);
640	        }
641	        return date;
642	    }
643	
644	    private boolean isWeekend(LocalDate date) {
645	        DayOfWeek day = date.getDayOfWeek();
646	        return day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY;
647	    }
648	
649	    /**
650	     * The number of owners that must already exist for a given day before a further create is flagged as a
651	     * bulk sign-up surge. When more than this many owners already share the new owner's registration date,
652	     * the created owner carries {@code bulkSignupWarning = true}.
653	     */
654	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
655	
656	    /**
657	     * Determines whether the owner being created lands on a day that already holds a bulk sign-up surge,
658	     * i.e. more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already share its {@code registrationDate}.
659	     * The count is taken before the new owner is persisted, so it excludes the owner being created, mirroring
660	     * the daily create-limit rule's accumulation path.
661	     *
662	     * @param registrationDate the registration date of the owner being created
663	     * @return {@code true} when more than 80 owners were already created on that day, otherwise {@code false}
664	     */
665	    private boolean isBulkSignupDay(LocalDate registrationDate) {
666	        long existing = this.clinicService.findAllOwners().stream()
667	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
668	            .count();
669	        return existing > BULK_SIGNUP_WARNING_THRESHOLD;
670	    }
671	
672	    /**
673	     * Rejects a create request whose supplied {@code registrationDate} is later than the server date. A
674	     * registration cannot be dated in the future. The check applies only to a date supplied in the request;
675	     * a {@code null} value (which is later defaulted to the server date) is accepted, and the comparison is
676	     * made against the supplied value before any business-day adjustment.
677	     *
678	     * @param registrationDate the registration date supplied in the request, or {@code null} when omitted
679	     * @throws FutureRegistrationDateException if a supplied registration date is later than the server date
680	     */
681	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
682	        if (registrationDate == null) {
683	            return;
684	        }
685	        LocalDate today = LocalDate.now();
686	        if (registrationDate.isAfter(today)) {
687	            throw new FutureRegistrationDateException(registrationDate, today);
688	        }
689	    }
690	
691	    private void rejectDailyLimitReached(LocalDate registrationDate) {
692	        long existing = this.clinicService.findAllOwners().stream()
693	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
694	            .count();
695	        if (existing >= DAILY_OWNER_LIMIT) {
696	            throw new DailyOwnerLimitExceededException(registrationDate, DAILY_OWNER_LIMIT);
697	        }
698	    }
699	
700	    /**
701	     * Rejects a create request whose owner collides with an existing owner on the single derived
702	     * {@code identityKey}. This one key consolidates the former separate telephone, email and household
703	     * duplicate checks: the create is rejected only when the new owner's WHOLE identity key exactly equals
704	     * an existing owner's. Because the (normalized) telephone is part of the key, two members of the same
705	     * household (same {@code householdId}) with different telephones have different keys and are both
706	     * allowed; only an exact full-key match is a duplicate. The owner's {@code householdId} has already
707	     * been computed (deterministically from the last name and postcode) before this check runs, so the
708	     * key compared here is the same one that is later returned.
709	     *
710	     * @param owner the owner being created, with normalized fields and its computed {@code householdId} set
711	     * @throws DuplicateIdentityException if an existing owner has the same identity key
712	     */
713	    private void rejectDuplicateIdentity(Owner owner) {
714	        String key = identityKey(owner);
715	        boolean taken = this.clinicService.findAllOwners().stream()
716	            .filter(existing -> !isDeleted(existing))
717	            .anyMatch(existing -> key.equals(identityKey(existing)));
718	        if (taken) {
719	            throw new DuplicateIdentityException(key);
720	        }
721	    }
722	
723	    /**
724	     * Flags a soft (possible) duplicate on the owner being created. A soft match is an existing owner that,
725	     * while not a hard {@code identityKey} duplicate (that stronger check has already run), shares this
726	     * owner's last name (compared case-insensitively) and exact postcode but carries a different normalized
727	     * telephone. When at least one such owner exists, {@code possibleDuplicate} is set {@code true} and
728	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match, for
729	     * determinism); otherwise {@code possibleDuplicate} is set {@code false} and no match id is recorded. A
730	     * new owner with no postcode has nothing to match on and is never a possible duplicate.
731	     * <p>
732	     * A declared household member ({@code sharesHousehold}) is never flagged: sharing a last name and
733	     * postcode is now exactly the household key, so such an owner is a known household member rather than
734	     * a suspected duplicate.
735	     *
736	     * @param owner the owner being created, with normalized telephone and validated postcode already set
737	     * @param sharesHousehold whether the create declared the owner a household member
738	     */
739	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
740	        Integer matchId = null;
741	        if (!sharesHousehold && owner.getPostcode() != null) {
742	            matchId = this.clinicService.findAllOwners().stream()
743	                .filter(existing -> !isDeleted(existing))
744	                .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName())
745	                    && owner.getPostcode().equals(existing.getPostcode())
746	                    && !telephonesEqual(owner.getTelephone(), existing.getTelephone()))
747	                .map(Owner::getId)
748	                .filter(id -> id != null)
749	                .min(Comparator.naturalOrder())
750	                .orElse(null);
751	        }
752	        owner.setPossibleDuplicate(matchId != null);
753	        owner.setPossibleDuplicateOf(matchId);
754	    }
755	
756	    private boolean telephonesEqual(String a, String b) {
757	        return a == null ? b == null : a.equals(b);
758	    }
759	
760	    /**
761	     * Whether an existing owner has been soft-deleted. A soft-deleted owner is retained and still
762	     * readable, but is ignored by the create endpoint's duplicate and identity checks.
763	     *
764	     * @param owner an existing owner
765	     * @return {@code true} when the owner is flagged deleted, otherwise {@code false}
766	     */
767	    private boolean isDeleted(Owner owner) {
768	        return Boolean.TRUE.equals(owner.getDeleted());
769	    }
770	
771	    /**
772	     * Derives an owner's {@code identityKey}: the normalized telephone, the email (or an empty string when
773	     * absent) and the household id (or an empty string when absent), joined by {@code '|'} in that order
774	     * (e.g. {@code '+61412345678||a1b2c3d4e5f6a7b8'} for an owner with no email but a shared household).
775	     * Telephone and email are stored already normalized, so the stored values are used directly.
776	     *
777	     * @param owner the owner whose identity key is being derived
778	     * @return the owner's identity key
779	     */
780	    private String identityKey(Owner owner) {
781	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
782	        String email = owner.getEmail() == null ? "" : owner.getEmail();
783	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
784	        return telephone + "|" + email + "|" + householdId;
785	    }
786	
787	    /**
788	     * Computes the owner's deterministic {@code householdId}: the first 12 hex characters of the SHA-256
789	     * digest of {@code '<normalizedLastName>|<postcode>'}, where the last name is normalized with
790	     * {@link #normalizeForComparison} and an absent postcode contributes an empty string. Because the
791	     * identifier is a pure function of last name and postcode, any two owners sharing those values share
792	     * the household automatically, with no cross-owner mutation. The value is assigned to every owner,
793	     * whether or not {@code sharesHousehold} was requested.
794	     *
795	     * @param owner the owner being created, with its validated postcode already set
796	     * @return the deterministic household identifier
797	     */
798	    private String computeHouseholdId(Owner owner) {
799	        String normalizedLastName = normalizeForComparison(owner.getLastName());
800	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
801	        return sha256Hex(normalizedLastName + "|" + postcode).substring(0, 12);
802	    }
803	
804	    /**
805	     * Rejects a create request whose owner would join an existing household without declaring it. The
806	     * household is keyed on the computed {@code householdId} (derived from last name and postcode), so any
807	     * existing owner sharing that identifier is already a member of the same household; a further owner is a
808	     * household duplicate. The check is bypassed when the request opted in via {@code sharesHousehold}, in
809	     * which case the owner is created as a declared household member. The (stronger) exact identity-key
810	     * check has already run, so a full duplicate is rejected regardless of {@code sharesHousehold}.
811	     *
812	     * @param owner the owner being created, with its computed {@code householdId} already assigned
813	     * @throws HouseholdDuplicateException if an existing owner already shares the household
814	     */
815	    private void rejectHouseholdDuplicate(Owner owner) {
816	        String householdId = owner.getHouseholdId();
817	        boolean shared = this.clinicService.findAllOwners().stream()
818	            .filter(existing -> !isDeleted(existing))
819	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
820	        if (shared) {
821	            throw new HouseholdDuplicateException(householdId);
822	        }
823	    }
824	
825	    /**
826	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
827	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
828	     * lower-cased.
829	     *
830	     * @param value the raw value to normalize (may be {@code null})
831	     * @return the normalized value, or an empty string when {@code value} is {@code null}
832	     */
833	    private String normalizeForComparison(String value) {
834	        if (value == null) {
835	            return "";
836	        }
837	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
838	    }
839	}
